def risky_calculator(expr):
    result = eval(expr)
    if result == float("inf") or result == float("-inf"):
        raise ZeroDivisionError("Division resulted in infinity")
    return result

def fetch_user_data(user_id):
    users = {"42": "Alice", "7": "Bob", "99": "Charlie"}
    return users.get(str(user_id))

def robust_agent(task):
    if task.startswith("calc:"):
        expr = task.split(":", 1)[1].strip()
        try:
            result = risky_calculator(expr)
            return {"task": task, "result": result, "status": "ok"}
        except ValueError as e:
            return {"task": task, "result": f"Invalid input: {e}", "status": "error"}
        except ZeroDivisionError as e:
            return {"task": task, "result": f"Math error: {e}", "status": "error"}
    elif task.startswith("user:"):
        uid = task.split(":", 1)[1].strip()
        result = fetch_user_data(uid)
        if result is None:
            return {"task": task, "result": "User not found", "status": "error"}
        return {"task": task, "result": result, "status": "ok"}
    else:
        return {"task": task, "result": "Unknown command", "status": "error"}
